use App\Traits\HasAuditFields;

class Invoice extends Model
{
    use HasAuditFields;
}

use App\Traits\NormalizesAddresses;

class Customer extends Model
{
    use NormalizesAddresses;

    protected static function booted(): void
    {
        static::saving(function (self $model) {
            $model->normalizeEmail('email');
            $model->normalizePhone('phone');
            $model->normalizeZip('zip_code');
        });
    }
}

use App\Traits\NormalizesArrays;

class Setting extends Model
{
    use NormalizesArrays;

    protected $casts = [
        'options' => 'array',
    ];

    protected static function booted(): void
    {
        static::saving(function (self $model) {
            $model->ensureJsonAttributesAreEncoded(['options']);
        });
    }
}

use Illuminate\Support\Str;

public function generateUniqueSlug(string $source): string
{
    $base     = Str::slug($source);
    $slug     = $base;
    $attempts = 0;
    $maxAttempts = 20;

    do {
        if ($attempts > 0) {
            $slug = $base . '-' . Str::random(4);
        }
        $attempts++;
    } while (static::where('slug', $slug)->exists() && $attempts < $maxAttempts);

    if ($attempts >= $maxAttempts) {
        Log::warning("Slug generation hit attempt limit for base: {$base}");
        $slug = $base . '-' . Str::uuid()->toString();
    }

    return $slug;
}

use App\Traits\NormalizesAddresses;

class Contact extends Model
{
    use NormalizesAddresses;
}

protected static function booted(): void
{
    static::saving(function (self $model) {
        $model->normalizeEmail('email');
        $model->normalizeEmail('billing_email');
        $model->normalizePhone('phone');
        $model->normalizePhone('mobile');
        $model->normalizeZip('zip_code');
        $model->normalizeZip('billing_zip');
        $model->normalizeBillingCountry('billing_country');
        $model->normalizeShippingCountry('shipping_country');
        $model->normalizeStateField('state');
    });
}

public function getTotalAmountAttribute(): float
{
    return (float) $this->items()->sum('amount');
}

public function getIsOverdueAttribute(): bool
{
    $dueDate = $this->getAttribute('due_date');
    if (!$dueDate) return false;
    return now()->greaterThan($dueDate);
}

public function getCachedTotalAttribute(): float
{
    return cache()->remember(
        "model_{$this->getKey()}_total",
        now()->addMinutes(10),
        fn () => (float) $this->items()->sum('amount')
    );
}
